const neoDatabase=data;
const databaseByLanguage=data;
function searchNeoFindDatabase(query,language="pl"){
 const q=String(query??"").trim().toLocaleLowerCase(language),list=data[language]||data.pl;
 return list.filter(item=>String(item.title||"").toLocaleLowerCase(language).includes(q)||String(item.desc||"").toLocaleLowerCase(language).includes(q)||(item.keywords||[]).some(k=>String(k).toLocaleLowerCase(language).includes(q)));
}
